// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    // fuzz the newOwner address; the rule: when called by current owner, owner() must become newOwner
    function testFuzz_property(address newOwner) public {
        // keep domain wide but avoid zero address as an OK choice (still admissible though)
        // get the initial owner (default zero for newly deployed C)
        address initialOwner = c.owner();

        // we need to make the call as the current owner. For freshly deployed C, owner is address(0).
        // If owner == address(0), we simulate setting ownership by directly calling transferOwnership from address(0).
        // vm.prank can set msg.sender to any address (including 0) for the call.

        // Ensure the caller is the current owner so the onlyOwner modifier allows the call.
        vm.prank(initialOwner);
        // perform the call; we don't expect revert since caller is owner
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // If the call succeeded, the invariant of the reference implementation is that c.owner() == newOwner.
        // The mutant that removed the assignment will make this false for some newOwner values.
        if (ok) {
            assertTrue(c.owner() == newOwner);
        } else {
            // If call reverted (shouldn't under reference given correct onlyOwner and caller), still assert false to fail
            // but keep behavior consistent: require ok to be true under reference
            assertTrue(ok);
        }
    }
}
